/// <summary>
/// getVarianceSummary's answer: how the journal's lines stand, and the ones needing a decision (at most 500).
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountVarianceSummaryResponse
{
    boolean success;
    str errorCode;
    int totalLines;
    int openLines;
    int firstCounted;
    int matched;
    int mismatch;
    int recount;
    int approved;
    int emptyConfirmed;
    boolean truncated;
    List lines;
}

Method.Source:
